<?php
$title='API Usage & Costs';$subtitle='Every paid API call counted – free limits, projections and overage cost';
$C=Usage::catalog();
if(is_post()){
  $o=[];
  foreach(($_POST['svc']??[]) as $k=>$x)if(isset($C[$k]))$o[$k]=['price'=>max(0,(float)($x['price']??0)),'free'=>max(0,(float)($x['free']??0))];
  foreach(($_POST['mdl']??[]) as $k=>$x){$k=trim($k);if($k!==''&&($x['in']!==''||$x['out']!==''))$o['_models'][$k]=['in'=>max(0,(float)$x['in']),'out'=>max(0,(float)$x['out'])];}
  if(($n=trim($_POST['new_model']??''))!=='')$o['_models'][$n]=['in'=>max(0,(float)($_POST['new_in']??0)),'out'=>max(0,(float)($_POST['new_out']??0))];
  Settings::set('usage_prices',je($o));
  Settings::set('usd_rate',max(0.0001,(float)($_POST['usd_rate']??84)));
  flash('Prices saved. New calls use these prices; past costs stay as recorded.');redirect(url('usage'));}
$M=Usage::month();$P=Usage::prices();$D=Usage::daily(30);
$rate=(float)setting('usd_rate',setting('currency','INR')==='USD'?'1':'84');$sym=setting('currency_symbol','₹');
$loc=fn($usd)=>setting('currency','INR')==='USD'?'':' <span class="muted">≈ '.$sym.number_format($usd*$rate,$usd*$rate<100?2:0).'</span>';
$usd=fn($v)=>'$'.number_format($v,$v<10?2:0);
$cost=array_sum(array_column($M,'cost'));$proj=array_sum(array_column($M,'proj_cost'));$calls=array_sum(array_column($M,'calls'));
$warn=array_filter($M,fn($m)=>$m['free']>0&&$m['proj']>$m['free']);
$ops=DB::all("SELECT service,op,SUM(calls) calls,SUM(units_in) uin,SUM(units_out) uout,SUM(cost) cost,SUM(errors) err FROM api_usage WHERE day>=DATE_FORMAT(CURDATE(),'%Y-%m-01') GROUP BY service,op ORDER BY cost DESC,calls DESC LIMIT 40");
$fmt=fn($m)=>$m['unit']==='tokens'?number_format($m['in']/1000,1).'k in · '.number_format($m['out']/1000,1).'k out':number_format($m['units'],$m['unit']==='minutes'?1:0).' '.$m['unit'];
// 30-day chart
$days=[];for($i=29;$i>=0;$i--){$d=date('Y-m-d',strtotime("-$i day"));$days[$d]=['c'=>(float)($D[$d]['cost']??0),'n'=>(int)($D[$d]['calls']??0)];}
$mx=max(0.01,max(array_column($days,'c')));$mn=max(1,max(array_column($days,'n')));
$W=900;$H=180;$bw=$W/30;
$svg='<svg class="chart" viewBox="0 0 '.$W.' '.($H+26).'" role="img" aria-label="Daily API cost, last 30 days">';
foreach([0,.5,1] as $g){$y=$H-$g*$H+2;$svg.='<line x1="0" x2="'.$W.'" y1="'.$y.'" y2="'.$y.'" stroke="#EEF0F5"/><text x="2" y="'.($y-4).'" font-size="10" fill="#98A0B3">'.e($usd($mx*$g)).'</text>';}
$i=0;$pts=[];foreach($days as $d=>$v){$h=$v['c']/$mx*($H-14);$x=$i*$bw+4;$svg.='<rect x="'.round($x,1).'" y="'.round($H-$h+2,1).'" width="'.round($bw-8,1).'" height="'.round(max($h,$v['c']>0?2:0),1).'" rx="4" fill="url(#ug)"><title>'.e(date('d M',strtotime($d)).': '.$usd($v['c']).' · '.$v['n'].' calls').'</title></rect>';$pts[]=round($x+($bw-8)/2,1).','.round($H-$v['n']/$mn*($H-14)+2,1);if($i%5===0||$i===29)$svg.='<text x="'.round($x+($bw-8)/2,1).'" y="'.($H+18).'" font-size="10.5" fill="#98A0B3" text-anchor="middle">'.date('d M',strtotime($d)).'</text>';$i++;}
$svg.='<polyline points="'.implode(' ',$pts).'" fill="none" stroke="#F97316" stroke-width="2" stroke-linejoin="round" opacity=".8"/><defs><linearGradient id="ug" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#8B5CF6"/><stop offset="1" stop-color="#6366F1"/></linearGradient></defs></svg>';
$sc=['google_places'=>'orange','serpapi'=>'amber','pagespeed'=>'green','anthropic'=>'violet','web_search'=>'pink','openai'=>'teal','openrouter'=>'indigo','gemini'=>'blue','groq'=>'rose','deepseek'=>'sky','whatsapp'=>'green','voice_sarvam'=>'pink','voice_bland'=>'pink','voice_vapi'=>'pink','voice_retell'=>'pink','email'=>'blue','gcal'=>'teal'];
?>
<div class="stats"><?=kpi('Cost this month',$usd($cost),'activity','violet',$loc($cost).' · '.date('F'))?><?=kpi('Projected by month end',$usd($proj),'target','indigo',$loc($proj).' at the current pace')?><?=kpi('API calls this month',number_format($calls),'zap','sky',count($M).' services used')?><?=kpi('Free limits at risk',count($warn),'alert',$warn?'rose':'green',$warn?'<span class="dn">'.e(implode(', ',array_map(fn($m)=>$m['name'],$warn))).'</span>':'all within free limits')?></div>
<?php if($warn):?><div class="al al-warn"><?=icon('alert')?><span><b>Heads-up:</b> at the current pace you will go over the free limit for <?=e(implode(', ',array_map(fn($m)=>$m['name'],$warn)))?> this month. Extra usage is billed at the price shown below.</span></div><?php endif?>
<div class="card"><div class="card-h"><h3><span class="hi c-violet"><?=icon('activity')?></span>Last 30 days</h3><div class="row sm muted"><span class="row nw" style="gap:6px"><i style="width:10px;height:10px;border-radius:3px;background:#7C5CF0;display:inline-block"></i>Cost</span><span class="row nw" style="gap:6px"><i style="width:14px;height:2px;background:#F97316;display:inline-block"></i>Calls</span></div></div><?=$svg?></div>
<div class="card p0"><div class="card-h"><h3><span class="hi c-sky"><?=icon('db')?></span>By service – <?=date('F Y')?></h3><span class="muted sm">Prices in USD · resets on the 1st</span></div><?php if(!$M):?><div class="empty sm"><?=icon('activity')?><p>No API calls recorded yet this month. Usage appears here as soon as you search, audit, write reports or send messages.</p></div><?php else:?><div class="tw"><table class="tbl usage-t"><thead><tr><th>Service</th><th>Used</th><th>Free limit</th><th class="num">Projected</th><th class="num">Cost so far</th><th class="num">Projected cost</th><th class="num">Errors</th></tr></thead><tbody><?php foreach($M as $k=>$m):$pc=$m['pct'];$cl=$pc===null?'g':($pc>=100?'r':($pc>=75?'a':'g'));?><tr><td><div class="who"><span class="avc c-<?=$sc[$k]??'gray'?>"><?=icon(in_array($k,['google_places','serpapi'],true)?'map':(strpos($k,'voice_')===0?'mic':($k==='email'?'mail':($k==='whatsapp'||$k==='whatsapp_api'?'wa':($k==='gcal'?'cal':($k==='pagespeed'?'zap':'spark'))))))?></span><div class="biz"><b><?=e($m['name'])?></b><small><?=$m['url']?'<a class="lnk" href="'.e($m['url']).'" target="_blank" rel="noopener">Pricing ↗</a>':''?><?=$m['unit']!=='tokens'&&$m['price']?' · $'.rtrim(rtrim(number_format($m['price'],4),'0'),'.').' per '.rtrim($m['unit'],'s'):''?></small></div></div></td><td class="nowrap"><b><?=$fmt($m)?></b><?php if($m['per']==='day'):?><small class="muted" style="display:block">today: <?=number_format($m['used'])?></small><?php endif?></td><td style="min-width:170px"><?php if($m['free']>0):?><div class="pb <?=$cl?>"><i style="width:<?=min(100,(int)$pc)?>%"></i></div><small class="pbm"><?=$pc?>% of <?=number_format($m['free'])?> / <?=$m['per']?></small><?php else:?><span class="muted sm"><?=$m['unit']==='tokens'?'Pay as you go':($m['price']?'No free tier':'Free')?></span><?php endif?></td><td class="num nowrap"><?=$m['unit']==='tokens'?'—':number_format($m['proj']).($m['free']>0&&$m['proj']>$m['free']?' <span class="bdg c-rose sm">over</span>':'')?></td><td class="num nowrap"><b><?=$usd($m['cost'])?></b></td><td class="num nowrap"><?=$usd($m['proj_cost'])?></td><td class="num"><?=$m['errors']?'<span class="red">'.$m['errors'].'</span>':'0'?></td></tr><?php endforeach?></tbody></table></div><?php endif?></div>
<?php if($ops):?><div class="card p0"><div class="card-h"><h3><span class="hi c-amber"><?=icon('list')?></span>Breakdown by action</h3></div><div class="tw"><table class="tbl"><thead><tr><th>Service</th><th>Action</th><th class="num">Calls</th><th class="num">Units in / out</th><th class="num">Cost</th></tr></thead><tbody><?php foreach($ops as $o):?><tr><td><?=e($C[$o['service']][0]??$o['service'])?></td><td><code><?=e($o['op']?:'—')?></code></td><td class="num"><?=number_format($o['calls'])?><?=$o['err']?' <small class="red">('.$o['err'].' failed)</small>':''?></td><td class="num muted sm"><?=$o['uin']||$o['uout']?number_format($o['uin']).' / '.number_format($o['uout']):'—'?></td><td class="num"><?=$usd($o['cost'])?></td></tr><?php endforeach?></tbody></table></div></div><?php endif?>
<form method="post" class="card"><?=csrf_field()?><div class="card-h"><h3><span class="hi c-green"><?=icon('tag')?></span>Prices &amp; free limits</h3><button class="btn btn-p btn-sm"><?=icon('check')?>Save prices</button></div><p class="sm muted mt0">Defaults reflect public list prices (USD) and may change – check each provider's pricing page and adjust to your plan. Costs are estimates; your provider's bill is final.</p><label style="max-width:320px">1 USD in <?=e(setting('currency','INR'))?><input type="number" step="0.0001" name="usd_rate" value="<?=e($rate)?>"></label>
<details class="opt"><summary><span class="hi c-sky"><?=icon('db')?></span>API services (price per unit, free units)</summary><div class="tw mt"><table class="tbl"><thead><tr><th>Service</th><th>Unit</th><th>USD per unit</th><th>Free units</th><th>Note</th></tr></thead><tbody><?php foreach($C as $k=>$c):if($c[2]==='tokens')continue;?><tr><td><b><?=e($c[0])?></b></td><td class="sm muted"><?=e(rtrim($c[2],'s'))?> · per <?=$c[5]?></td><td><input type="number" step="0.000001" min="0" name="svc[<?=$k?>][price]" value="<?=e($P[$k]['price'])?>" style="width:120px"></td><td><input type="number" step="1" min="0" name="svc[<?=$k?>][free]" value="<?=e($P[$k]['free'])?>" style="width:120px"></td><td class="xs muted" style="max-width:340px"><?=e($c[7])?></td></tr><?php endforeach?></tbody></table></div></details>
<details class="opt"><summary><span class="hi c-violet"><?=icon('spark')?></span>AI models (USD per 1 million tokens)</summary><div class="tw mt"><table class="tbl"><thead><tr><th>Model</th><th>Input</th><th>Output</th></tr></thead><tbody><?php foreach($P['_models'] as $k=>$x):?><tr><td><code><?=e($k)?></code></td><td><input type="number" step="0.001" min="0" name="mdl[<?=e($k)?>][in]" value="<?=e($x['in'])?>" style="width:110px"></td><td><input type="number" step="0.001" min="0" name="mdl[<?=e($k)?>][out]" value="<?=e($x['out'])?>" style="width:110px"></td></tr><?php endforeach?><tr><td><input name="new_model" placeholder="Add model id, e.g. gpt-4.1-nano"></td><td><input type="number" step="0.001" min="0" name="new_in" style="width:110px"></td><td><input type="number" step="0.001" min="0" name="new_out" style="width:110px"></td></tr></tbody></table></div><p class="hint">The active model is <code><?=e(AI::model()?:'not set')?></code>. If a model isn't listed, its token counts are still tracked but its cost shows as $0.</p></details></form>
